at::Tensor WhereSelfKernelKunlunxin(
    const at::Tensor& condition, const at::Tensor& self, const at::Tensor& other) {
  const at::ScalarType result_dtype = at::result_type(self, other);
  if (!kunlunxin::KunlunxinSupportsDtype(result_dtype)) {
    return at::where(condition.cpu(), self.cpu(), other.cpu())
        .to(self.device());
  }
  auto self_c = self.scalar_type() == result_dtype ? self : self.to(result_dtype);
  auto other_c = other.to(self.device(), result_dtype);
  const std::vector<int64_t> out_shape = at::infer_size(
      at::infer_size(condition.sizes(), self_c.sizes()), other_c.sizes());
  at::Tensor cond_c =
      condition.device() == self.device() ? condition : condition.to(self.device());
  at::Tensor cond_b = cond_c.expand(out_shape).contiguous();
  at::Tensor self_b = self_c.expand(out_shape).contiguous();
  at::Tensor other_b = other_c.expand(out_shape).contiguous();
  kunlunxin::KunlunxinDeviceGuard guard(self_b);
  xpytorch::xpu::api::Context* const context =
      kunlunxin::GetKunlunxinContext(self_b);
  at::Tensor out = at::empty(out_shape, self_b.options());
  kunlunxin::XdnnTensorWrapper t_cond(cond_b);
  kunlunxin::XdnnTensorWrapper t_self(self_b);
  kunlunxin::XdnnTensorWrapper t_other(other_b);
  kunlunxin::XdnnTensorWrapper t_out(out);
  KUNLUNXIN_EXEC(
      where_self,
      xdnn_pytorch::where_self(
          context,
          t_cond.get(),
          t_self.get(),
          t_other.get(),
          t_out.get()));
  return out;
}

